// The text renderer behind `generateTypes` (codegen.ts) and the checked-in
// built-in augmentation (builtin-types.ts, regenerated by codegen.test.ts).
// Pure: no I/O, no clock; the same input gives the same text.
import type { ContentFieldKind } from '@givegold/shared'
import type { ContentTypeField, ContentTypeSummary } from '@givegold/shared/content-api'

/**
 * How the augmentation adds the types to `BackgoldTypeMap`:
 *
 * - `own`: one member per type (`post: BackgoldFields['post']`). What a
 *   consumer's generated file uses: an own member may narrow a member the
 *   map inherits, so an org that added fields to a built-in type gets its
 *   own shape without a conflict.
 * - `inherited`: `interface BackgoldTypeMap extends BackgoldFields {}`. What
 *   the shipped built-in file uses, so a consumer's own members override it.
 */
export type AugmentationStyle = 'own' | 'inherited'

export interface RenderTypesInput {
  types: readonly ContentTypeSummary[]
  /** Comment lines printed first, each without the leading `// `. */
  header: readonly string[]
  moduleName: string
  style: AugmentationStyle
}

const IDENTIFIER = /^[A-Za-z_$][A-Za-z0-9_$]*$/

const ESCAPES: Record<string, string> = { '\\': '\\\\', "'": "\\'", '\n': '\\n', '\r': '\\r', '\t': '\\t' }

/** A single-quoted TypeScript string literal for `s`. */
export function quote(s: string): string {
  const body = s.replace(
    // eslint-disable-next-line no-control-regex
    /[\\'\u0000-\u001f\u007f\u{2028}\u{2029}]/gu,
    (c) => ESCAPES[c] ?? `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`,
  )
  return `'${body}'`
}

/** A property name: bare when `key` is an identifier, quoted otherwise. */
function propertyName(key: string): string {
  return IDENTIFIER.test(key) ? key : quote(key)
}

/** Text safe on one `//` comment line. */
function commentText(s: string): string {
  // eslint-disable-next-line no-control-regex
  return s.replace(/[\u0000-\u001f\u007f\u{2028}\u{2029}]+/gu, ' ').trim()
}

const REFERENCE = "{ kind: 'entry'; label: string; slug: string } | { kind: string; label: string; url?: string }"

const KIND_TYPES: Record<ContentFieldKind, string | null> = {
  short_text: 'string',
  long_text: 'string',
  rich_text: 'string',
  link: 'string',
  image: '{ url: string }',
  pdf: '{ url: string; file_name: string; size_bytes: number }',
  date: 'string',
  datetime: 'string',
  boolean: 'boolean',
  reference: REFERENCE,
  // Built from the field's choices.
  choice: null,
  choices: null,
  list: 'string[]',
}

/** The union of a field's choices as string literals, in the api's order, duplicates dropped; null when it has none. */
function choiceUnion(field: ContentTypeField): { text: string; members: number } | null {
  const choices = [...new Set(field.choices ?? [])]
  if (choices.length === 0) return null
  return { text: choices.map(quote).join(' | '), members: choices.length }
}

/** `type` plus the comment for one field; `unknown` for a kind this version does not know. */
function fieldType(field: ContentTypeField): { type: string; known: boolean } {
  const kind = field.kind as string
  if (!Object.hasOwn(KIND_TYPES, kind)) return { type: 'unknown', known: false }
  let type = KIND_TYPES[kind as ContentFieldKind]
  if (field.kind === 'choice') type = choiceUnion(field)?.text ?? 'string'
  if (field.kind === 'choices') {
    const union = choiceUnion(field)
    type = union ? (union.members > 1 ? `(${union.text})[]` : `${union.text}[]`) : 'string[]'
  }
  return { type: field.required ? type! : `${type} | null`, known: true }
}

function fieldLine(field: ContentTypeField): string {
  const { type, known } = fieldType(field)
  const label = commentText(field.label)
  const note = known ? label : `${label} (unknown field kind ${quote(commentText(field.kind))})`.trim()
  return `    ${propertyName(field.key)}: ${type};${note ? ` // ${note}` : ''}`
}

function typeBlock(type: ContentTypeSummary): string[] {
  const name = propertyName(type.key)
  if (type.fields.length === 0) return [`  ${name}: {};`]
  return [`  ${name}: {`, ...type.fields.map(fieldLine), '  };']
}

/** The source of a module that augments `moduleName`'s `BackgoldTypeMap` with `types`. */
export function renderTypes({ types, header, moduleName, style }: RenderTypesInput): string {
  // `{}` is the shape of a type with no fields; the disable keeps a
  // consumer's no-empty-object-type lint rule off a file nobody edits.
  const lines: string[] = ['/* eslint-disable */', ...header.map((h) => `// ${commentText(h)}`)]
  if (types.length === 0) {
    lines.push('export interface BackgoldFields {}')
  } else {
    lines.push('export interface BackgoldFields {', ...types.flatMap(typeBlock), '}')
  }
  lines.push('', `declare module ${quote(moduleName)} {`)
  if (style === 'inherited' || types.length === 0) {
    const heritage = style === 'inherited' ? ' extends BackgoldFields' : ''
    lines.push(`  interface BackgoldTypeMap${heritage} {}`)
  } else {
    lines.push('  interface BackgoldTypeMap {')
    for (const t of types) lines.push(`    ${propertyName(t.key)}: BackgoldFields[${quote(t.key)}];`)
    lines.push('  }')
  }
  lines.push('}', '')
  return lines.join('\n')
}
